∀ {C : Type u} [inst : Foundations.Categories.Category C] {F : Foundations.Categories.Functor C (Type v)} {A : C}
  (α : Foundations.Categories.NatTrans (Foundations.Categories.homFunctor A) F) {X : C}
  (h : Foundations.Categories.Category.Hom A X), α.app X h = F.map h (α.app A (Foundations.Categories.Category.id A))

{G : Type u} →
  [inst : Foundations.Algebra.Group G] →
    Foundations.Categories.Category.Hom { } { } → Foundations.Categories.Iso { } { }

∀ {G : Type u} {H : Type v} [inst : Foundations.Algebra.Group G] [inst_1 : Foundations.Algebra.Group H]
  (toFun toFun_1 : G → H) (e_toFun : toFun = toFun_1) (map_mul : ∀ (a b : G), toFun (a * b) = toFun a * toFun b),
  { toFun := toFun, map_mul := map_mul } = { toFun := toFun_1, map_mul := ⋯ }

∀ (f : Foundations.Numbers.R → Foundations.Numbers.R) {a b : Foundations.Numbers.R}
  {l₁ : List (Foundations.Numbers.R × Foundations.Numbers.R)}
  (l₂ : List (Foundations.Numbers.R × Foundations.Numbers.R)),
  a.IsTagged l₁ b →
    Foundations.Numbers.R.rsum f a (l₁ ++ l₂) = Foundations.Numbers.R.rsum f a l₁ + Foundations.Numbers.R.rsum f b l₂

∀ {G : Type u} [inst : Foundations.Algebra.Group G] {N : Foundations.Algebra.Subgroup G} [hN : N.Normal] {K : Type v}
  [inst_1 : Foundations.Algebra.Group K] (f : Foundations.Algebra.Hom G K) (hf : ∀ (x : G), x ∈ N → f.toFun x = 1)
  (a : G), (Foundations.Algebra.QuotientGroup.lift f hf).toFun (Foundations.Algebra.QuotientGroup.mk N a) = f.toFun a

∀ {C : Type u} [inst : Foundations.Categories.Category C] {X Y P Q : C} {π₁ : Foundations.Categories.Category.Hom P X}
  {π₂ : Foundations.Categories.Category.Hom P Y} {ρ₁ : Foundations.Categories.Category.Hom Q X}
  {ρ₂ : Foundations.Categories.Category.Hom Q Y} (hP : Foundations.Categories.IsProduct X Y P π₁ π₂)
  (hQ : Foundations.Categories.IsProduct X Y Q ρ₁ ρ₂),
  Foundations.Categories.Category.comp (hP.uniqueIso hQ).hom ρ₁ = π₁ ∧
    Foundations.Categories.Category.comp (hP.uniqueIso hQ).hom ρ₂ = π₂

∀ {C : Type u} [inst : Foundations.Categories.Category C] {X Y Z P : C} {f : Foundations.Categories.Category.Hom X Z}
  {g : Foundations.Categories.Category.Hom Y Z} {p₁ : Foundations.Categories.Category.Hom P X}
  {p₂ : Foundations.Categories.Category.Hom P Y} (hP : Foundations.Categories.IsPullback f g P p₁ p₂) {W : C}
  {h k : Foundations.Categories.Category.Hom W P},
  Foundations.Categories.Category.comp h p₁ = Foundations.Categories.Category.comp k p₁ →
    Foundations.Categories.Category.comp h p₂ = Foundations.Categories.Category.comp k p₂ → h = k

∀ {C : Type u} [inst : Foundations.Categories.Category C] {X Y Z P Q : C} {f : Foundations.Categories.Category.Hom X Z}
  {g : Foundations.Categories.Category.Hom Y Z} {p₁ : Foundations.Categories.Category.Hom P X}
  {p₂ : Foundations.Categories.Category.Hom P Y} {q₁ : Foundations.Categories.Category.Hom Q X}
  {q₂ : Foundations.Categories.Category.Hom Q Y} (hP : Foundations.Categories.IsPullback f g P p₁ p₂)
  (hQ : Foundations.Categories.IsPullback f g Q q₁ q₂) (i : Foundations.Categories.Iso P Q),
  Foundations.Categories.Category.comp i.hom q₁ = p₁ →
    Foundations.Categories.Category.comp i.hom q₂ = p₂ → i = hP.uniqueIso hQ

{α : Type u} →
  {e : Nat → α} →
    (M : Foundations.Sets.SquareAbsorb.PSq e) → ({ x // M.dom x } → { x // ¬M.dom x }) → α → { x // M.dom x }

∀ (σ : Nat → Foundations.Logic.FO.Term Foundations.Logic.FO.Arith) (d n : Nat),
  Foundations.Logic.FO.liftN d σ n =
    if n < d then Foundations.Logic.FO.Term.var n else Foundations.Logic.FO.Term.rename (fun x => x + d) (σ (n - d))

∀ (θ : Foundations.Numbers.R) (n : Nat),
  { re := 0, im := θ } ^ n =
    { re := Foundations.Numbers.R.cosCoeff n * θ ^ n, im := Foundations.Numbers.R.sinCoeff n * θ ^ n }

{G : Type u} →
  [inst : Foundations.Algebra.Group G] →
    (H : Foundations.Algebra.Subgroup G) → Foundations.Algebra.Subgroup { x // x ∈ Foundations.Algebra.normalizer H }

∀ {C : Type u} [inst : Foundations.Categories.Category C] {X Y P Q : C} {π₁ : Foundations.Categories.Category.Hom P X}
  {π₂ : Foundations.Categories.Category.Hom P Y} {ρ₁ : Foundations.Categories.Category.Hom Q X}
  {ρ₂ : Foundations.Categories.Category.Hom Q Y} (hP : Foundations.Categories.IsProduct X Y P π₁ π₂)
  (hQ : Foundations.Categories.IsProduct X Y Q ρ₁ ρ₂) (i : Foundations.Categories.Iso P Q),
  Foundations.Categories.Category.comp i.hom ρ₁ = π₁ →
    Foundations.Categories.Category.comp i.hom ρ₂ = π₂ → i = hP.uniqueIso hQ

(G : Type u) →
  [inst : Foundations.Algebra.Group G] →
    Foundations.Algebra.Iso G { x // x ∈ (Foundations.Algebra.leftRegular G).range }

∀ {C : Type u} [inst : Foundations.Categories.Category C] {X Y P : C} {π₁ : Foundations.Categories.Category.Hom P X}
  {π₂ : Foundations.Categories.Category.Hom P Y} (hP : Foundations.Categories.IsProduct X Y P π₁ π₂) {V W : C}
  (a : Foundations.Categories.Category.Hom V W) (f : Foundations.Categories.Category.Hom W X)
  (g : Foundations.Categories.Category.Hom W Y),
  Foundations.Categories.Category.comp a (hP.lift f g) =
    hP.lift (Foundations.Categories.Category.comp a f) (Foundations.Categories.Category.comp a g)

{α : Type u} →
  {e : Nat → α} →
    (M : Foundations.Sets.SquareAbsorb.PSq e) → ({ x // M.dom x } → { x // ¬M.dom x }) → α × α → { x // M.dom x }

{S : Type v} →
  [inst : Foundations.Algebra.CommRing S] →
    (A : Foundations.Algebra.Subring S) → Foundations.Algebra.CommRing { x // x ∈ A }

{C : Type u} →
  [inst : Foundations.Categories.Category C] →
    {X Y : C} → Foundations.Categories.Iso X Y → Foundations.Categories.Iso { unop := X } { unop := Y }

∀ {C : Type u} [inst : Foundations.Categories.Category C] {X Y E E' : C} {f g : Foundations.Categories.Category.Hom X Y}
  {e : Foundations.Categories.Category.Hom E X} {e' : Foundations.Categories.Category.Hom E' X}
  (hE : Foundations.Categories.IsEqualizer f g E e) (hE' : Foundations.Categories.IsEqualizer f g E' e')
  (i : Foundations.Categories.Iso E E'), Foundations.Categories.Category.comp i.hom e' = e → i = hE.uniqueIso hE'

∀ {C : Type u} [inst : Foundations.Categories.Category C] {X Y P : C} {π₁ : Foundations.Categories.Category.Hom P X}
  {π₂ : Foundations.Categories.Category.Hom P Y} (hP : Foundations.Categories.IsProduct X Y P π₁ π₂) {W : C}
  {h k : Foundations.Categories.Category.Hom W P},
  Foundations.Categories.Category.comp h π₁ = Foundations.Categories.Category.comp k π₁ →
    Foundations.Categories.Category.comp h π₂ = Foundations.Categories.Category.comp k π₂ → h = k

∀ {G : Type u} [inst : Foundations.Algebra.Group G] [inst_1 : Foundations.Algebra.FiniteType G]
  (H : Foundations.Algebra.Subgroup G),
  Foundations.Algebra.FiniteType.card { x // x ∈ H.inNormalizer } = Foundations.Algebra.FiniteType.card { x // x ∈ H }

∀ {C : Type u} [inst : Foundations.Categories.Category C] {X Y E : C} {f g : Foundations.Categories.Category.Hom X Y}
  {e : Foundations.Categories.Category.Hom E X} (hE : Foundations.Categories.IsEqualizer f g E e) {W : C}
  {h k : Foundations.Categories.Category.Hom W E},
  Foundations.Categories.Category.comp h e = Foundations.Categories.Category.comp k e → h = k

∀ {G : Type u} [inst : Foundations.Algebra.Group G] {N : Foundations.Algebra.Subgroup G}
  {P : Foundations.Algebra.QuotientGroup N → Prop},
  (∀ (a : G), P (Foundations.Algebra.QuotientGroup.mk N a)) → ∀ (q : Foundations.Algebra.QuotientGroup N), P q
